#include <iostream>
#include <vector>
#include <cmath>
#include <iomanip>

// Point representation
struct Point {
    double x;
    double y;
};

// Legacy structured calculation decoupled from the point list
double compute_distance(const Point& p1, const Point& p2) {
    double dx = p1.x - p2.x;
    double dy = p1.y - p2.y;
    return std::sqrt(dx * dx + dy * dy);
}

int main() {
    int n = 0;
    if (!(std::cin >> n) || n < 2) {
        return 0;
    }

    std::vector<Point> pts(n);
    for (int i = 0; i < n; ++i) {
        std::cin >> pts[i].x >> pts[i].y;
    }

    // 1-based indexing search matching textbook logic
    double dmax = compute_distance(pts[0], pts[1]);
    int imax = 1, jmax = 2;

    for (int i = 0; i < n - 1; ++i) {
        for (int j = i + 1; j < n; ++j) {
            double d = compute_distance(pts[i], pts[j]);
            if (d > dmax) {
                dmax = d;
                imax = i + 1;
                jmax = j + 1;
            }
        }
    }

    std::cout << std::fixed << std::setprecision(2);
    std::cout << "Doan thang lon nhat co do dai bang: " << dmax << "\n";
    std::cout << "Di qua 2 diem co chi so la " << imax << " va " << jmax << "\n";
    return 0;
}

#include <iostream>
#include <vector>
#include <cmath>
#include <iomanip>

// Encapsulating the point sequence into a class DayDiem
class DayDiem {
private:
    int n;
    std::vector<float> x;
    std::vector<float> y;

public:
    // Method defined inside class body (matching inline do_dai from page 217)
    float do_dai(int i, int j) const {
        return std::sqrt(std::pow(x[i] - x[j], 2) + std::pow(y[i] - y[j], 2));
    }

    // Method prototype declared here, defined outside using ::
    void nhapsl(std::istream& in);

    // Helper method to execute the search algorithm
    void tim_cap_xa_nhat() const;
};

// Defining member function outside class body with scope resolution operator ::
void DayDiem::nhapsl(std::istream& in) {
    if (!(in >> n) || n <= 0) {
        n = 0;
        return;
    }
    // Using 1-based indexing as in the original textbook malloc((n+1)*sizeof(float))
    x.assign(n + 1, 0.0f);
    y.assign(n + 1, 0.0f);
    for (int i = 1; i <= n; ++i) {
        in >> x[i] >> y[i];
    }
}

void DayDiem::tim_cap_xa_nhat() const {
    if (n < 2) return;
    float dmax = do_dai(1, 2);
    int imax = 1, jmax = 2;

    for (int i = 1; i <= n - 1; ++i) {
        for (int j = i + 1; j <= n; ++j) {
            float d = do_dai(i, j);
            if (d > dmax) {
                dmax = d;
                imax = i;
                jmax = j;
            }
        }
    }

    std::cout << std::fixed << std::setprecision(2);
    std::cout << "Doan thang lon nhat co do dai bang: " << dmax << "\n";
    std::cout << "Di qua 2 diem co chi so la " << imax << " va " << jmax << "\n";
}

int main() {
    DayDiem dd;
    dd.nhapsl(std::cin);
    dd.tim_cap_xa_nhat();
    return 0;
}
